// PaymentServiceHandler is an implementation of the
// io.github.will413028.hawkr.payment.grpc.PaymentService service.
type PaymentServiceHandler interface {
	// 建立支付交易
	CreatePayment(context.Context, *connect.Request[payment.CreatePaymentRequest]) (*connect.Response[payment.CreatePaymentResponse], error)
	// 查詢支付詳情
	GetPayment(context.Context, *connect.Request[payment.GetPaymentRequest]) (*connect.Response[payment.GetPaymentResponse], error)
	// §2A.3.6 / §2A.6 查詢同 order_id 的所有付款嘗試（含 CLOSED_BY_SWITCH / 副 row）
	GetPaymentHistory(context.Context, *connect.Request[payment.GetPaymentHistoryRequest]) (*connect.Response[payment.GetPaymentHistoryResponse], error)
	// #2501 賣家視角付款歷程：由 Gateway 解出的現任 store_id 驗店家歸屬（一般 GetPaymentHistory 已收斂為 buyer-only）
	GetSellerPaymentHistory(context.Context, *connect.Request[payment.GetSellerPaymentHistoryRequest]) (*connect.Response[payment.GetSellerPaymentHistoryResponse], error)
	// 查詢付款狀態（公開，免驗證 — 供付款結果回調頁面使用）
	GetPublicPaymentStatus(context.Context, *connect.Request[payment.GetPublicPaymentStatusRequest]) (*connect.Response[payment.GetPublicPaymentStatusResponse], error)
	// 同步查詢支付狀態（呼叫 PayUni Query API）
	SyncPaymentStatus(context.Context, *connect.Request[payment.SyncPaymentStatusRequest]) (*connect.Response[payment.SyncPaymentStatusResponse], error)
	// 關閉交易
	ClosePayment(context.Context, *connect.Request[payment.ClosePaymentRequest]) (*connect.Response[payment.ClosePaymentResponse], error)
	// 依訂單編號關閉付款交易（Order Service 取消訂單時呼叫，內部 RPC）
	ClosePaymentByOrderNo(context.Context, *connect.Request[payment.ClosePaymentByOrderNoRequest]) (*connect.Response[payment.ClosePaymentByOrderNoResponse], error)
	// 依訂單編號反查活躍/最終付款狀態（internal-only，Order Service 逾期取消前守門用）
	// 免權限（isInternalCall()）；以 order_no 為鍵回傳該訂單 canonical 交易的付款狀態
	GetActivePaymentStatusByOrderNo(context.Context, *connect.Request[payment.GetActivePaymentStatusByOrderNoRequest]) (*connect.Response[payment.GetActivePaymentStatusByOrderNoResponse], error)
	// 建立退款
	CreateRefund(context.Context, *connect.Request[payment.CreateRefundRequest]) (*connect.Response[payment.CreateRefundResponse], error)
	// 查詢退款詳情
	GetRefund(context.Context, *connect.Request[payment.GetRefundRequest]) (*connect.Response[payment.GetRefundResponse], error)
	// 查詢交易的所有退款
	GetRefundsByTradeNo(context.Context, *connect.Request[payment.GetRefundsByTradeNoRequest]) (*connect.Response[payment.GetRefundsByTradeNoResponse], error)
	// 取得付款結果回調頁面（含 HTML + Deep Link，供 Gateway 透傳）
	GetPaymentReturnPage(context.Context, *connect.Request[payment.GetPaymentReturnPageRequest]) (*connect.Response[payment.GetPaymentReturnPageResponse], error)
	// 以 opaque redirect_id 取回付款中轉表單 canonical 欄位（Gateway GET /payment/redirect?id= 用，一次性消費，#1394 反射 XSS 修復）
	GetPaymentRedirectForm(context.Context, *connect.Request[payment.GetPaymentRedirectFormRequest]) (*connect.Response[payment.GetPaymentRedirectFormResponse], error)
	// 發動撥款指示（代理商模式：買家確認收貨後，由 Order Service 呼叫）
	GrantPayment(context.Context, *connect.Request[payment.GrantPaymentRequest]) (*connect.Response[payment.GrantPaymentResponse], error)
	// 批次查詢付款 provider 狀態（Order 聚合用，收斂規範 §6.3）
	BatchGetProviderStatusByOrderIds(context.Context, *connect.Request[payment.BatchGetProviderStatusByOrderIdsRequest]) (*connect.Response[payment.BatchGetProviderStatusByOrderIdsResponse], error)
	// 批次查詢退款 provider 狀態 by case_ids（AfterSales 聚合用）
	BatchGetRefundProviderStatusByCaseIds(context.Context, *connect.Request[payment.BatchGetRefundProviderStatusByCaseIdsRequest]) (*connect.Response[payment.BatchGetRefundProviderStatusResponse], error)
	// 批次查詢退款 provider 狀態 by order_ids（Order 聚合用，取每個 order 最新一筆 payment_refunds）
	BatchGetRefundProviderStatusByOrderIds(context.Context, *connect.Request[payment.BatchGetRefundProviderStatusByOrderIdsRequest]) (*connect.Response[payment.BatchGetRefundProviderStatusResponse], error)
	// 信用卡付款 Return 處理（Gateway 接收 PayUni Form POST 後呼叫）
	// 解密 + 驗簽 + 更新交易狀態 + 組裝 Deep Link
	HandlePaymentPageReturn(context.Context, *connect.Request[payment.HandlePaymentPageReturnRequest]) (*connect.Response[payment.HandlePaymentPageReturnResponse], error)
	// Apple Pay on Web Merchant Validation：對 Apple validationURL 取 merchantSession
	// 使用 Apple Pay Merchant Identity Certificate (PEM + Key) 進行 mTLS POST，原樣透傳 Apple 回應
	// 詳見 05 號設計書 §5.11
	ValidateApplePayMerchant(context.Context, *connect.Request[payment.ValidateApplePayMerchantRequest]) (*connect.Response[payment.ValidateApplePayMerchantResponse], error)
	// 列付款異常（FAILED / EXPIRED / CONFLICT 或 rescue_action 有值）
	ListPaymentTransactionsForAdmin(context.Context, *connect.Request[payment.ListPaymentTransactionsForAdminRequest]) (*connect.Response[payment.ListPaymentTransactionsForAdminResponse], error)
	// 取付款詳情（Admin 對帳用，含 grant_* 撥款欄位、rescue、重複付款等）
	GetPaymentTransactionForAdmin(context.Context, *connect.Request[payment.GetPaymentTransactionForAdminRequest]) (*connect.Response[payment.GetPaymentTransactionForAdminResponse], error)
	// 列退款異常（FAILED 或處理超時 24h）
	ListRefundsForAdmin(context.Context, *connect.Request[payment.ListRefundsForAdminRequest]) (*connect.Response[payment.ListRefundsForAdminResponse], error)
	// 取退款詳情
	GetRefundForAdmin(context.Context, *connect.Request[payment.GetRefundForAdminRequest]) (*connect.Response[payment.GetRefundForAdminResponse], error)
	// 列撥款異常（grant_status 非成功）
	ListGrantsForAdmin(context.Context, *connect.Request[payment.ListGrantsForAdminRequest]) (*connect.Response[payment.ListGrantsForAdminResponse], error)
	// ==== 服務間：發票日期與金額所需的付款事實（58 號 §7.1.2 步驟 5 ②、註 2）====
	// invoice-service 的 order.paid consumer 專用；唯讀，**不改支付服務任何狀態機**。
	// 走 52 號 HMAC 內部授權四 header，client deadline 3s。
	// 既有的 AdminPaymentTransactionDetail 雖然也帶 provider_paid_at，但那是 admin 面 DTO，
	// 服務間直用違反角色分離（Proto 管理規範 §5.1）。
	GetPaymentFactsInternal(context.Context, *connect.Request[payment.GetPaymentFactsInternalRequest]) (*connect.Response[payment.GetPaymentFactsInternalResponse], error)
}

